content.query:
let startOfToday = startofday(now()); 
let offsetWeek = 6d; 
let endTimeWeek = startOfToday - offsetWeek; 
let offsetMonth = 29d;
let endTimeMonth = startOfToday - offsetMonth; 
let snapShots = SecurityRegulatoryCompliance 
| where IsSnapshot == true 
| extend Day = startofday(TimeGenerated)
| summarize day_snapshot = max(TimeGenerated), week_snapshot = maxif(TimeGenerated, TimeGenerated <=  endTimeWeek), month_snapshot = maxif(TimeGenerated, TimeGenerated <=  endTimeMonth) by RegulatoryComplianceSubscriptionId, ComplianceStandard;


let relevantStandard = SecurityRegulatoryCompliance 
| where  RegulatoryComplianceSubscriptionId in ({Subscription:subid})
| extend standardName = replace('-', ' ',ComplianceStandard)
| where standardName in~ ({standard_name})
| extend Day = startofday(TimeGenerated)
| join kind = leftouter (snapShots) on RegulatoryComplianceSubscriptionId, ComplianceStandard;

// current image
let curr =  relevantStandard
| where (IsSnapshot == true and Day == startofday(day_snapshot)) or (IsSnapshot == false and TimeGenerated > day_snapshot) 
| summarize arg_max(TimeGenerated, *) by ComplianceStandard, ComplianceControl, RecommendationId, RegulatoryComplianceSubscriptionId 
| summarize failed_ass = countif(State == "Failed"), skipped_ass = countif(State == "Skipped"), passed_ass = countif(State == "Passed") by ComplianceStandard, ComplianceControl 
| summarize passed = countif(failed_ass == 0 and (skipped_ass == 0 or (passed_ass > 0 and skipped_ass > 0))), total_controls_curr = count(), skipped = countif(failed_ass == 0 and skipped_ass > 0 and passed_ass == 0), failed = countif(failed_ass > 0) by ComplianceStandard 
| extend ratio_curr = (passed/todouble(total_controls_curr))*100; 


// last week image
let last_week = relevantStandard 
| where (IsSnapshot == true and Day == startofday(week_snapshot)) or (IsSnapshot == false and TimeGenerated > week_snapshot and Day <= endTimeWeek) 
| summarize arg_max(TimeGenerated, *) by ComplianceStandard, ComplianceControl, RecommendationId, RegulatoryComplianceSubscriptionId 
| summarize failed_ass = countif(State == "Failed"), skipped_ass = countif(State == "Skipped"), passed_ass = countif(State == "Passed") by ComplianceStandard, ComplianceControl 
| summarize passed = countif(failed_ass == 0 and (skipped_ass == 0 or (passed_ass > 0 and skipped_ass > 0))),total_controls_week = count(), skipped = countif(failed_ass == 0 and skipped_ass > 0 and passed_ass == 0), failed = countif(failed_ass > 0) by ComplianceStandard 
| extend ratio_week = (passed/todouble(total_controls_week))*100; 

// last month image
let last_month = relevantStandard 
| where (IsSnapshot == true and Day == startofday(month_snapshot)) or (IsSnapshot == false and TimeGenerated > month_snapshot and Day <= endTimeMonth) 
| summarize arg_max(TimeGenerated, *) by ComplianceStandard, ComplianceControl, RecommendationId, RegulatoryComplianceSubscriptionId 
| summarize failed_ass = countif(State == "Failed"), skipped_ass = countif(State == "Skipped"), passed_ass = countif(State == "Passed") by ComplianceStandard, ComplianceControl 
| summarize passed = countif(failed_ass == 0 and (skipped_ass == 0 or (passed_ass > 0 and skipped_ass > 0))),total_controls_month = count(), skipped = countif(failed_ass == 0 and skipped_ass > 0 and passed_ass == 0), failed = countif(failed_ass > 0) by ComplianceStandard 
| extend ratio_month = (passed/todouble(total_controls_month))*100; 

curr
|join kind = leftouter (last_week) on ComplianceStandard
| join kind = leftouter (last_month) on ComplianceStandard
| extend diffWeek = (ratio_curr - ratio_week)
| extend diffMonth = (ratio_curr - ratio_month)
| project ComplianceStandard, total_controls_curr, passed, skipped, failed, ratio_curr,  diffWeek, diffMonth
| order by ratio_curr asc

let startOfToday = startofday(now()); 
let offsetWeek = 6d; 
let endTimeWeek = startOfToday - offsetWeek; 
let offsetMonth = 29d;
let endTimeMonth = startOfToday - offsetMonth; 
let snapShots = SecurityRegulatoryCompliance 
| where ComplianceStandard == '{ComplianceStandard}'
| where IsSnapshot == true 
| extend Day = startofday(TimeGenerated)
| summarize day_snapshot = max(TimeGenerated), week_snapshot = maxif(TimeGenerated, TimeGenerated <=  endTimeWeek), month_snapshot = maxif(TimeGenerated, TimeGenerated <=  endTimeMonth) by RegulatoryComplianceSubscriptionId;

let relevantStandard = SecurityRegulatoryCompliance 
| where RegulatoryComplianceSubscriptionId in ({Subscription:subid})
| where ComplianceStandard == '{ComplianceStandard}'
| extend tempControl = iff(ComplianceStandard == "HIPAA-HITRUST", extract("\\.(..).*\\.", 1, ComplianceControl) , iff(ComplianceStandard == "ISO-27001:2013" or ComplianceStandard == "NIST-SP-800-171-R2", extract("^([^.]*.[^.]*)", 1, ComplianceControl) , extract("^([^.]+).", 1, ComplianceControl)))
| where tempControl == '{parent_control}'
| extend Day = startofday(TimeGenerated)
| join kind = leftouter (snapShots) on RegulatoryComplianceSubscriptionId;

// current image
let curr =  relevantStandard
| where (IsSnapshot == true and Day == startofday(day_snapshot)) or (IsSnapshot == false and TimeGenerated >  day_snapshot)
| summarize arg_max(TimeGenerated, *) by ComplianceControl, RecommendationId, RegulatoryComplianceSubscriptionId
| distinct ComplianceControl, RecommendationId, State
| summarize failed_ass_curr = countif(State == "Failed") by ComplianceControl;

// last week image
let last_week = relevantStandard
| where (IsSnapshot == true and Day == startofday(week_snapshot)) or (IsSnapshot == false and  TimeGenerated > week_snapshot and Day <= endTimeWeek)
| summarize arg_max(TimeGenerated, *) by ComplianceControl, RecommendationId, RegulatoryComplianceSubscriptionId
| distinct ComplianceControl, RecommendationId, State
| summarize failed_ass_week = countif(State == "Failed") by ComplianceControl;

// last month image
let last_month = relevantStandard
| where (IsSnapshot == true and Day == startofday(month_snapshot)) or (IsSnapshot == false and TimeGenerated > month_snapshot and Day <= endTimeMonth)
| summarize arg_max(TimeGenerated, *) by ComplianceControl, RecommendationId, RegulatoryComplianceSubscriptionId
| distinct ComplianceControl, RecommendationId, State
| summarize failed_ass_month = countif(State == "Failed") by ComplianceControl;


curr
| join kind = leftouter (last_week) on ComplianceControl
| join kind = leftouter (last_month) on ComplianceControl
| project ComplianceControl, failed_ass_curr, failed_ass_week, failed_ass_month
| order by failed_ass_curr desc

let startOfToday = startofday(now()); 
let offsetWeek = 6d; 
let offsetMonth = 29d;
let weekAgo = startOfToday - offsetWeek; 
let monthAgo = startOfToday - offsetMonth;

let revelantControl = SecurityRegulatoryCompliance
| where ComplianceStandard == '{ComplianceStandard}'
| where ComplianceControl == '{compliance_control}';

let lastControlSnapshot = revelantControl
| where IsSnapshot == true
| summarize arg_max(TimeGenerated, TimeGenerated) by ComplianceControl
| project lastSnapshotDay = startofday(TimeGenerated);

let controlsRecommandations = revelantControl // all the control's reccomendation in last snapshot
| where IsSnapshot == true
| extend day = startofday(TimeGenerated)
| where day in (lastControlSnapshot)
| distinct RecommendationId;

let relevantRecommandations = revelantControl
| where RegulatoryComplianceSubscriptionId in ({Subscription:subid})
| where RecommendationId in (controlsRecommandations);

let curr = relevantRecommandations
| summarize arg_max(TimeGenerated, *) by RecommendationId, RegulatoryComplianceSubscriptionId
| summarize failedResourcesSumCurr = sum(FailedResources) by RecommendationId, RecommendationName;

let last_week = relevantRecommandations
| where startofday(TimeGenerated) < weekAgo
| summarize arg_max(TimeGenerated, *) by RecommendationId, RegulatoryComplianceSubscriptionId
| summarize failedResourcesSumWeek = sum(FailedResources) by RecommendationId, RecommendationName;

let last_month = relevantRecommandations
| where startofday(TimeGenerated) <= monthAgo
| summarize arg_max(TimeGenerated, *) by RecommendationId, RegulatoryComplianceSubscriptionId
| summarize failedResourcesSumMonth = sum(FailedResources) by RecommendationId, RecommendationName;

curr
| join kind = leftouter (last_week) on RecommendationId
| join kind = leftouter (last_month) on RecommendationId
| project RecommendationName, RecommendationId, failedResourcesSumCurr, failedResourcesSumWeek, failedResourcesSumMonth
| order by failedResourcesSumCurr desc

