content.query:
// lookup all Status states seen in last month 
let pastMonth = SecurityIncident | where TimeGenerated > startofday(ago(30d)) | summarize by Status;
 SecurityIncident
// lookup Status states, from today only
| where TimeGenerated > ago(1d)
| summarize todayCount=count() by Status
| join kind=fullouter (pastMonth) on Status
| join (
 SecurityIncident 
 // from oldest suplied parameter until 24hrs ago 
 | where TimeGenerated between (startofday({TimeRange:start}) .. ago(1d))
 // get avg from oldest date to this time yesterday
 | summarize count() by Status , bin(TimeGenerated,1d)
 | summarize historyCount = round(avg(count_),2) by Status
 ) on $left.Status1 == $right.Status
| extend todayCount = iif(isempty(todayCount),0,todayCount)
 | extend trendIs = case(
        todayCount > historyCount,"Trending Up",
        todayCount == historyCount,"Equal",
        todayCount < historyCount,"Trending Down",
        Status2
 )
| project Status2, todayCount, historyCount, trendIs

SigninLogs
| where TimeGenerated {TimeRange}
| where Status.errorCode {SigninStatus}
| where UserPrincipalName =~ "{UPN}"
| where Id == "{SigninId}"
| distinct tostring(DeviceDetail), UserAgent

//Replace this with Brian's query and description
let starttime = 7d;
let endtime = 1d;
let LogonEvents=() { 
let logonSuccess=SecurityEvent 
| where EventID==4624
| where tolower(Computer) contains tolower("{Host}")
| where TargetUserName !endswith "$"
| where TargetUserName !contains "NETWORK SERVICE"
| where TargetUserName !contains "LOCAL SERVICE"
| where TargetUserName != "SYSTEM"
| project TimeGenerated, ComputerName=Computer, AccountName=TargetUserName, AccountDomain=TargetDomainName, IpAddress, ActionType='Logon';
let logonFail=SecurityEvent 
| where EventID==4625
| where tolower(Computer) contains tolower("{Host}")
| where TargetUserName !endswith "$"
| where TargetUserName !contains "NETWORK SERVICE"
| where TargetUserName !contains "LOCAL SERVICE"
| where TargetUserName != "SYSTEM"
| project TimeGenerated, ComputerName=Computer, AccountName=TargetUserName, AccountDomain=TargetDomainName, IpAddress, ActionType='LogonFailure';
logonFail 
| union logonSuccess
};
LogonEvents 
| where TimeGenerated > ago(endtime) 
| where ActionType == 'Logon' 
| summarize StartTimeUtc = min(TimeGenerated), EndTimeUtc = max(TimeGenerated), count() by ComputerName, AccountName 
| join kind=leftanti ( 
LogonEvents 
| where TimeGenerated between(ago(starttime)..ago(endtime)) 
| where ActionType == 'Logon' 
| summarize count() by ComputerName, AccountName 
) on ComputerName, AccountName 
//| summarize StartTimeUtc = min(StartTimeUtc), EndTimeUtc = max(EndTimeUtc), HostCount=dcount(ComputerName), HostSet=makeset(ComputerName, 10)  by AccountName, ComputerName
| summarize count() by AccountName
