let OnPremEvents = dynamic([4731, 4732, 4733, 4734, 4735, 4764, 4727, 4737, 4728, 4729, 4730, 4754, 4755, 4756, 4757, 4758]);
SecurityEvent
| where tolower(Computer) == tolower("{Host}")
| where Account == "{ChangeMaker:escape}"//@ or :escape escapes problematic characters
| where EventID in (OnPremEvents)
| extend ImpactedAccount = iff(MemberName == "-", MemberSid, MemberName)
| project TimeGenerated, Activity, ChangeMaker=Account, AccountType, Computer, ImpactedAccount, Group=TargetAccount

